<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import PendingDeployment from './PendingDeployment.vue'
import BuildInfoPanel from './BuildInfoPanel.vue'
import { scopeLabel } from './monitoring'
import RetentionPanel from './RetentionPanel.vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from './api'
import { ElMessage } from 'element-plus'
import { changedPatch, fields, formValue, getField } from './settings'
import { errorMessage, requestKey, type Settings, type Preview, type Job } from './monitoring'
let generation=0,disposed=false,actionVersion=0
const operation=ref(''),previewElement=ref<HTMLElement>()
function startAction(message:string){error.value='';feedback.value='';operation.value=message;return ++actionVersion}
function currentAction(version:number){return !disposed&&version===actionVersion}
function actionFailed(e:unknown,version:number){if(currentAction(version)){error.value=errorMessage(e);operation.value='';ElMessage.error('操作未完成，请查看下方固定提示')}}
const emailHealth=ref<{pending_email:number;email_enabled:boolean;email_recipients:string[]}>(), testConfirm=ref(false)
 const router = useRouter(), settings = ref<Settings>(), error = ref(''), feedback = ref(''), busy = ref(false), group = ref(String(useRoute().query.group||'公共监控')), preview = ref<Preview>()
const form = reactive<Record<string, unknown>>({}), groups = [...new Set(fields.map(f => f.group))], shown = computed(() => fields.filter(f => f.group === group.value))
async function load(){const current=++generation;try{const result=await api<Settings>('/api/settings');if(current!==generation||disposed)return;settings.value=result;for(const field of fields)form[field.path]=formValue(field,getField(result.values,field.path));preview.value=undefined;error.value='';try{const result=await api<typeof emailHealth.value>('/api/system/health');if(current===generation&&!disposed)emailHealth.value=result}catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}}catch(e){if(current===generation&&!disposed)error.value=errorMessage(e)}}
onUnmounted(()=>{disposed=true;generation++;actionVersion++})
function edit() { return { revision: settings.value?.revision || '', patch: changedPatch(settings.value?.values || {}, form) } }
async function inspect(){if(busy.value)return;busy.value=true;const current=startAction('正在校验配置并生成变更预览…');try{const result=await api<Preview>('/api/settings/preview','POST',edit());if(currentAction(current)){preview.value=result;operation.value='校验通过，请查看变更预览后选择保存或应用。';ElMessage.success('配置校验通过')}}catch(e){actionFailed(e,current)}finally{if(currentAction(current))busy.value=false}}
async function save(apply:boolean){if(busy.value)return;busy.value=true;const current=startAction(apply?'正在创建配置应用任务…':'正在保存配置…');try{if(apply){const job=await api<Job>('/api/deployments','POST',{request_key:requestKey(),revision:settings.value?.revision,kind:'apply',edit:edit()});if(currentAction(current)){operation.value='任务已创建，正在检查部署环境';ElMessage.success('任务已创建，正在检查部署环境');await router.push(`/deployments/${job.id}`)}}else{await api('/api/settings','PUT',edit());if(!currentAction(current))return;await load();if(currentAction(current)){feedback.value='配置已保存，尚未应用；请预览并应用待生效设置。';operation.value='';ElMessage.success('配置已保存，尚未应用')}}}catch(e){actionFailed(e,current)}finally{if(currentAction(current))busy.value=false}}
async function migrate() { busy.value = true; try { const job = await api<Job>('/api/deployments', 'POST', { request_key: requestKey(), revision: settings.value?.revision, kind: 'migrate' }); await router.push(`/deployments/${job.id}`) } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
async function testEmail(){busy.value=true;error.value='';try{const result=await api<{message:string}>('/api/notifications/email-test','POST',{});feedback.value=result.message;testConfirm.value=false}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false" /><el-alert v-if="feedback" :title="feedback" type="success" :closable="false" /><PendingDeployment :recovery="settings?.recovery"/><el-card v-if="settings?.pending_changes" shadow="never"><h3>已保存配置的应用状态</h3><p>{{!settings.pending_changes.known?'尚无可信应用记录，无法确认':settings.pending_changes.changes.length?'存在待应用修改':'可比较的配置已应用'}}</p><p v-if="settings.pending_changes.changes.length">范围：{{scopeLabel(settings.pending_changes.scope)}} · {{settings.pending_changes.restart?'需要部署或重建服务':'支持热加载'}} · 节点：{{settings.pending_changes.nodes.join('、')||'主服务器'}}</p><el-table v-if="settings.pending_changes.changes.length" :data="settings.pending_changes.changes"><el-table-column prop="field" label="配置项"/><el-table-column prop="effect" label="应用影响"/></el-table><p class="muted">{{settings.pending_changes.credential_note}}</p><el-button v-if="settings.pending_changes.changes.length" :disabled="busy||settings.pending_task" @click="inspect">预览待应用配置与表单修改</el-button></el-card><el-card shadow="never"><div class="filters"><el-select v-model="group" :disabled="busy"><el-option v-for="g in groups" :key="g" :label="g" :value="g" /></el-select><el-button :disabled="busy" @click="load">重新读取配置</el-button><router-link to="/backups?tab=deployment">部署配置备份 →</router-link></div><p class="muted">修改的是主服务器 YAML；账号密码请使用右上角“修改密码”。保存前自动备份，端口或协议变化可能使当前页面断线。</p><el-form label-position="top" :disabled="busy" @input="preview = undefined"><div class="form-grid"><el-form-item v-for="field in shown" :key="field.path" :label="field.label"><div class="full"><el-switch v-if="field.type === 'boolean'" v-model="form[field.path] as boolean" @change="preview = undefined" /><el-input v-else v-model="form[field.path] as string" :type="field.type === 'secret' ? 'password' : field.type === 'lines' ? 'textarea' : field.type === 'number' ? 'number' : 'text'" :rows="3" :autocomplete="field.type === 'secret' ? 'new-password' : 'off'" /><small class="muted">{{ field.hint }}</small></div></el-form-item></div></el-form><el-button :loading="busy" :disabled="!settings || settings.pending_task" @click="inspect">校验并预览变更</el-button></el-card>
<RetentionPanel v-if="group==='历史与备份'" />
<el-card v-if="group==='邮箱通知'" shadow="never"><h3>邮箱绑定与测试</h3><p>绑定表示配置 SMTP 发件账号和收件列表，不读取收件箱。待发送任务：{{emailHealth?.pending_email ?? '未知'}}；{{emailHealth?.email_enabled?'邮箱已开启':'邮箱关闭，未完成任务暂停'}}。</p><p>当前已应用收件人：{{emailHealth?.email_recipients?.join('、') || '未配置'}}</p><p class="muted">先保存并应用配置，再测试；已提交邮件服务器不代表已进入收件箱。旧任务保持原收件人。</p><el-button :disabled="!emailHealth?.email_enabled || busy" @click="testConfirm=true">发送测试邮件</el-button></el-card>
<el-dialog v-model="testConfirm" title="发送测试邮件" width="min(520px,96vw)"><p>将使用已应用配置向以下邮箱发送测试邮件：</p><p class="wrap">{{emailHealth?.email_recipients?.join('、')}}</p><template #footer><el-button @click="testConfirm=false">取消</el-button><el-button type="primary" :loading="busy" @click="testEmail">确认发送</el-button></template></el-dialog>
<div v-if="preview" ref="previewElement"><el-card shadow="never"><h3>变更预览</h3><p>应用范围：{{ scopeLabel(preview.scope) }}；{{ preview.restart ? '需要部署或重建服务' : '支持热加载' }}。</p><el-alert v-if="preview.changes.some(c => (c.field.startsWith('retention.') || c.field.endsWith('history_days') || c.field.endsWith('raw_hours')) && Number(c.after)<Number(c.before))" title="应用较短保留期限后，超期历史将自动删除；之后调大期限无法找回已删除记录。" type="warning" :closable="false"/><el-table :data="preview.changes"><el-table-column prop="field" label="字段" min-width="210" /><el-table-column label="原值"><template #default="{ row }"><pre class="wrap">{{ JSON.stringify(row.before) }}</pre></template></el-table-column><el-table-column label="新值"><template #default="{ row }"><pre class="wrap">{{ JSON.stringify(row.after) }}</pre></template></el-table-column><el-table-column prop="effect" label="影响" /></el-table><p v-if="!preview.changes.length" class="muted">本次表单没有新修改；应用仍会处理已经保存的待生效配置。</p><el-button :loading="busy" @click="save(false)">仅保存配置</el-button><el-button type="primary" :loading="busy" @click="save(true)">保存并应用</el-button></el-card></div>
<el-card v-if="getField(settings?.values || {}, 'central.monitoring.mode') === 'legacy'" shadow="never"><h3>迁移至 Go 一体化模式</h3><p>分批迁入现有保留期内的指标和日志，完成核对后接管告警并停用本项目 Prometheus、Alertmanager、Grafana、Loki。保留原数据和回退配置；不修改子服务器或业务网站。</p><el-button type="primary" :loading="busy" :disabled="settings?.pending_task" @click="migrate">迁移历史并切换</el-button></el-card>
<BuildInfoPanel/><div v-if="error||feedback||operation" class="settings-feedback-space" aria-hidden="true"></div><div v-if="error||feedback||operation" class="settings-operation-status" :role="error?'alert':'status'" aria-live="polite"><el-alert :title="error||feedback||operation" :type="error?'error':busy?'info':'success'" :closable="false" show-icon/><el-button v-if="preview" link type="primary" @click="previewElement?.scrollIntoView({block:'start',behavior:'smooth'})">查看变更预览</el-button></div></template>
<style scoped>.settings-feedback-space{height:30dvh}.settings-operation-status{position:fixed;bottom:16px;right:24px;width:min(760px,calc(100vw - 48px));z-index:20;background:var(--el-bg-color);border:1px solid var(--el-border-color);border-radius:8px;padding:10px;box-shadow:0 2px 12px #0002;overflow-wrap:anywhere;max-height:30dvh;overflow-y:auto}</style>
